import {DeckCodeOptions} from '../utils/deck-code';

/** Game data sets the site can draft from */
export type Dataset = 'wif' | 'wif-extended' | 'vanilla';

export interface DatasetConfig {
  /** Title shown on the drafter pages */
  title: string;
  /** Units and divisions generated by tools/wif-extractor */
  dataUrl: string;
  /** DLC list (vanilla only) */
  dlcUrl?: string;
  /** localStorage key of the draft in progress */
  draftStorageKey: string;
  /** How deck codes are written for this data set */
  deckCode: DeckCodeOptions;
}

export const DATASETS: Record<Dataset, DatasetConfig> = {
  wif: {
    title: 'WiF Deck Drafter',
    dataUrl: '/data/wif.json',
    draftStorageKey: 'deckDraftState_wif',
    // Decks made in game with WiF loaded carry the mod's Steam Workshop id
    // and use 17-bit unit ids (largest WiF unit id: 99999).
    deckCode: {mod: {workshopId: '3388575848', value: 1}, idBits: 17},
  },
  // WiF together with the divisions of the WiF_extended mod (Wagner, ...).
  // New divisions of that mod only need data/wif-extended.json regenerated.
  'wif-extended': {
    title: 'WiF Extended Deck Drafter',
    dataUrl: '/data/wif-extended.json',
    draftStorageKey: 'deckDraftState_wif-extended',
    // WiF_extended is a full mod on its own (WiF + new divisions), Steam
    // Workshop id from its Config.ini. Largest unit id 100022 fits 17 bits.
    deckCode: {mod: {workshopId: '3825673031', value: 1}, idBits: 17},
  },
  vanilla: {
    title: 'Vanilla Deck Draft',
    dataUrl: '/data/vanilla.json',
    dlcUrl: '/data/vanilla-dlc.json',
    draftStorageKey: 'deckDraftState_vanilla',
    deckCode: {},
  },
};

export function isDataset(value: unknown): value is Dataset {
  return value === 'wif' || value === 'wif-extended' || value === 'vanilla';
}
